import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../styles/home.css';

const Home = () => {
  const [posts, setPosts] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [suggestions, setSuggestions] = useState([]);

  // Fetch data from the backend (mocked here with dummy data)
  useEffect(() => {
    // Example API calls (replace with actual backend routes later)
    // axios.get('http://localhost:5000/api/posts')
    //   .then(res => setPosts(res.data))
    //   .catch(err => console.log(err));

    setPosts([
      { id: 1, user: 'Aman', content: 'Just got placed at Amazon!', likes: 10, comments: 2 },
      { id: 2, user: 'Simran', content: 'Join my DSA bootcamp!', likes: 5, comments: 1 },
    ]);

    setNotifications([
      { id: 1, text: 'New message from Rohan' },
      { id: 2, text: 'Your post received 5 new likes' },
    ]);

    setSuggestions([
      { id: 1, name: 'Harpreet Singh', branch: 'CSE' },
      { id: 2, name: 'Mandeep Kaur', branch: 'IT' },
    ]);
  }, []);

  return (
    <div className="home-container">
      {/* Left Sidebar: Suggestions */}
      <div className="left-sidebar">
        <h3>Suggestions</h3>
        {suggestions.map(s => (
          <div key={s.id} className="suggestion-card">
            <p>{s.name}</p>
            <small>{s.branch}</small>
            <button>Connect</button>
          </div>
        ))}
      </div>

      {/* Main Feed: Posts */}
      <div className="main-feed">
        <h2>Home Feed</h2>
        {posts.map(post => (
          <div key={post.id} className="post-card">
            <h4>{post.user}</h4>
            <p>{post.content}</p>
            <div className="post-actions">
              <span>❤️ {post.likes}</span>
              <span>💬 {post.comments}</span>
            </div>
          </div>
        ))}
      </div>

      {/* Right Sidebar: Notifications */}
      <div className="right-sidebar">
        <h3>Notifications</h3>
        {notifications.map(n => (
          <div key={n.id} className="notification-card">
            <p>{n.text}</p>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Home;
